mapper.select:
select count(1)
from `ry_rental`.`ry_rental_user_member`
where member_id = #{memberId}
  and merchant_user_id = #{merchantUserId}
  and del_flag = '0'

mapper.update:
update `ry_rental`.`ry_rental_user_member`
set member_role = #{memberRole},
    warehouse_scope_type = #{warehouseScopeType},
    update_by = #{updateBy},
    update_time = sysdate()
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and merchant_user_id = #{merchantUserId}
  and del_flag = '0'
